script:
customers = frappe.db.sql("""
	select c.name, c.customer_name, c.mobile_no, c.legacy_due_amount,
		pu.user as portal_user, u.enabled as user_enabled, u.last_login
	from `tabCustomer` c
	left join `tabPortal User` pu on pu.parent = c.name and pu.parenttype = 'Customer'
	left join `tabUser` u on u.name = pu.user
	order by c.customer_name
""", as_dict=True)

active = []
not_onboarded = []
seen_mobiles = {}
for c in customers:
	if c.mobile_no:
		seen_mobiles.setdefault(c.mobile_no, []).append(c.name)

for c in customers:
	row = {
		"customer": c.name,
		"customer_name": c.customer_name,
		"mobile_no": c.mobile_no,
		"due": float(c.legacy_due_amount or 0),
		"last_login": str(c.last_login) if c.last_login else None,
	}
	if c.portal_user:
		row["status"] = "active" if c.user_enabled else "revoked"
		active.append(row)
	else:
		not_onboarded.append(row)

needs_review = [m for m, names in seen_mobiles.items() if len(names) > 1]
review_rows = [c for c in customers if c.mobile_no in needs_review]

frappe.response["message"] = {
	"active": active,
	"not_onboarded": [r for r in not_onboarded if not r["mobile_no"] or r["mobile_no"] not in needs_review],
	"needs_review": [
		{"customer": c.name, "customer_name": c.customer_name, "mobile_no": c.mobile_no, "due": float(c.legacy_due_amount or 0)}
		for c in review_rows
	],
}

rows = frappe.get_all(
	"Storefront Announcement",
	fields=["name", "title", "announcement_type", "message", "is_active", "start_date", "end_date"],
	order_by="modified desc",
)
frappe.response["message"] = {"announcements": rows}

def clean_name(name):
	if not name:
		return name
	return name.split(" [ERP-")[0].strip()


orders = frappe.get_all(
	"Sales Order",
	fields=["name", "customer", "customer_name", "transaction_date", "delivery_date", "grand_total", "status"],
	order_by="creation desc",
	limit_page_length=300,
)

order_names = [o.name for o in orders]
item_rows = []
if order_names:
	item_rows = frappe.get_all(
		"Sales Order Item",
		filters={"parent": ["in", order_names]},
		fields=["parent", "item_name", "qty"],
	)

items_by_order = {}
for row in item_rows:
	items_by_order.setdefault(row.parent, []).append(row)

result = []
for o in orders:
	items = items_by_order.get(o.name, [])
	if items:
		summary = items[0].item_name
		if len(items) > 1:
			summary += " + " + str(len(items) - 1) + " more"
	else:
		summary = ""
	result.append({
		"name": o.name,
		"customer": o.customer,
		"customer_name": clean_name(o.customer_name),
		"transaction_date": o.transaction_date,
		"delivery_date": o.delivery_date,
		"grand_total": o.grand_total,
		"status": o.status,
		"item_count": len(items),
		"item_summary": summary,
	})

frappe.response["message"] = result

def clean_name(name):
	if not name:
		return name
	return name.split(" [ERP-")[0].strip()


name = frappe.form_dict.get("name")
if not name:
	frappe.throw("Order name is required")

doc = frappe.get_doc("Sales Order", name)

address = None
if doc.customer_address:
	address = frappe.db.get_value("Address", doc.customer_address, "address_line1")

frappe.response["message"] = {
	"name": doc.name,
	"customer_name": clean_name(doc.customer_name),
	"transaction_date": doc.transaction_date,
	"delivery_date": doc.delivery_date,
	"status": doc.status,
	"grand_total": doc.grand_total,
	"contact_mobile": doc.contact_mobile,
	"address": address,
	"items": [
		{
			"item_name": i.item_name,
			"qty": i.qty,
			"rate": i.rate,
			"amount": i.amount,
		}
		for i in doc.items
	],
}

name = frappe.form_dict.get("name")
if not name:
	frappe.throw("Order name is required")

doc = frappe.get_doc("Sales Order", name)
doc.update_status("Closed")

frappe.response["message"] = {"status": doc.status}
